 r=subprocess.run(args,input=CODE,capture_output=True,timeout=120,env=clean,cwd='/opt/yunipals-unified/releases/41e5b5fdb1ae4623fb742a9cc77e6e5c578d48845c9102bbafbb06880045987b/apps/yunipals-indexer')
